        public static ObjectId Block(Database db, Transaction tr, string layer)
        {
            return SteelDrawing.Block(db, tr, BlockName, btr =>
            {
                for (int i = 0; i + 3 < Lines.Length; i += 4)
                    SteelDrawing.Put(btr, tr, new Line(new Point3d(Lines[i], Lines[i + 1], 0), new Point3d(Lines[i + 2], Lines[i + 3], 0)), layer);
                for (int i = 0; i + 4 < Arcs.Length; i += 5)
                    SteelDrawing.Put(btr, tr, new Arc(new Point3d(Arcs[i], Arcs[i + 1], 0), Arcs[i + 2], Arcs[i + 3] * Math.PI / 180, Arcs[i + 4] * Math.PI / 180), layer);
            });
        }
    }
